return ['domain'=>'taxopress-pro','plural-forms'=>'nplurals=2; plural=n != 1 && n != 2 && n != 3 && (n % 10 == 4 || n % 10 == 6 || n % 10 == 9);','language'=>'fil','project-id-version'=>'TaxoPress Pro 3.51.0','pot-creation-date'=>'2026-07-22T18:23:43+00:00','po-revision-date'=>'2026-07-22 18:33+0000','x-generator'=>'WP-CLI 2.12.0','messages'=>['TaxoPress Pro'=>'TaxoPress Pro','https://wordpress.org/plugins/simple-tags/'=>'https://wordpress.org/plugins/simple-tags/','TaxoPress allows you to create and manage Tags, Categories, and all your WordPress taxonomy terms.'=>'TaxoPress allows you to create and manage Tags, Categories, and all your WordPress taxonomy terms.','TaxoPress'=>'TaxoPress','https://taxopress.com'=>'https://taxopress.com','License key'=>'License key','Status'=>'Status','Your license key provides access to updates and support.'=>'Your license key provides access to updates and support.','Activate License'=>'Activate License','Synonyms'=>'Synonyms','This feature allows you to associate additional words with each term. For example, "website" can have synonyms such as "websites", "web site", and "web pages".'=>'This feature allows you to associate additional words with each term. For example, "website" can have synonyms such as "websites", "web site", and "web pages".','Linked Terms'=>'Linked Terms','This feature allows you to connect terms. When the main term or any of these terms are added to the post, all the other terms will be added also.'=>'This feature allows you to connect terms. When the main term or any of these terms are added to the post, all the other terms will be added also.','Shortcode Name'=>'Shortcode Name','Add'=>'Add','Enter the shortcode name without [ ] or parameters.'=>'Enter the shortcode name without [ ] or parameters.','Search Block'=>'Search Block','Search...'=>'Search...','Search and select blocks.'=>'Search and select blocks.','Element tag'=>'Element tag','Add Element'=>'Magdagdag ng Elemento','New Element'=>'Bagong Elemento','OpenAI is an external service that can scan your content and suggest relevant terms. %1sClick here for details%2s.'=>'Ang OpenAI ay isang panlabas na serbisyo na maaaring suriin ang iyong nilalaman at magmungkahi ng mga kaugnay na termino. %1sMag-click dito para sa mga detalye%2s.','False'=>'Mali','True'=>'Tama','This will automatically add new terms from the OpenAI service. Before use, please test carefully using the preview feature.'=>'Ito ay awtomatikong magdaragdag ng mga bagong termino mula sa serbisyo ng OpenAI. Bago gamitin, mangyaring subukan nang maingat gamit ang tampok na preview.','Enable OpenAI'=>'I-enable ang OpenAI','API Key'=>'API Key','Enter your OpenAI API Key.'=>'Ilagay ang iyong OpenAI API Key.','gpt-3.5-turbo'=>'gpt-3.5-turbo','gpt-4o-mini'=>'gpt-4o-mini','gpt-4o'=>'gpt-4o','chatgpt-4o-latest'=>'chatgpt-4o-latest','gpt-5'=>'gpt-5','gpt-5-mini'=>'gpt-5-mini','gpt-5-nano'=>'gpt-5-nano','o3-mini'=>'o3-mini','o1-mini'=>'o1-mini','o1'=>'o1','OpenAI Models'=>'Mga Modelong OpenAI','Some models availability depends on your subscription and access.'=>'Ang pagkakaroon ng ilang modelo ay depende sa iyong subscription at access.','Show Term Post Count'=>'Ipakita ang Bilang ng Post sa Term','This will show the number of posts attached to the terms.'=>'Ipinapakita nito ang bilang ng mga post na nakakabit sa mga term.','Cache Results'=>'I-cache ang Mga Resulta','By caching the results locally, new API requests will not be made unless the post title or content changes. This saves API usage.'=>'Sa pamamagitan ng pag-cache ng mga resulta nang lokal, hindi gagawa ng bagong mga kahilingan sa API maliban kung magbago ang pamagat o nilalaman ng post. Nakakatipid ito sa paggamit ng API.','OpenAI Prompt (Beta)'=>'OpenAI Prompt (Beta)','%1s Click here for prompt documentation. %2s'=>'%1s I-click dito para sa dokumentasyon ng prompt. %2s','OpenAI Max Tokens'=>'OpenAI Max Tokens','Maximum tokens for OpenAI response. You can increase this when using {site} placeholder with many terms.'=>'Maksimum na mga token para sa tugon ng OpenAI. Maaari mong dagdagan ito kapag gumagamit ng placeholder na {site} na may maraming term.','IBM Watson is an external service that can scan your content and suggest relevant terms. %1sClick here for details%2s.'=>'Ang IBM Watson ay isang panlabas na serbisyo na maaaring suriin ang iyong nilalaman at magmungkahi ng mga kaugnay na term. %1sI-click dito para sa mga detalye%2s.','This will automatically add new terms from the IBM Watson service. Before use, please test carefully using the preview feature.'=>'Awtomatiko nitong idaragdag ang mga bagong term mula sa serbisyo ng IBM Watson. Bago gamitin, mangyaring subukan nang maingat gamit ang preview na tampok.','Enable IBM Watson'=>'Paganahin ang IBM Watson','API URL'=>'API URL','Enter your IBM Watson API URL.'=>'Ilagay ang iyong IBM Watson API URL.','Enter your IBM Watson API Key.'=>'Ilagay ang iyong IBM Watson API Key.','This integration is no longer actively supported. If you still need to use it, you can enable it in the Legacy AI Sources settings.'=>'Ang integrasyong ito ay hindi na aktibong sinusuportahan. Kung kailangan mo pa rin itong gamitin, maaari mo itong paganahin sa mga setting ng Legacy AI Sources.','Dandelion is an external service that can scan your content and suggest relevant terms. %1sClick here for details%2s.'=>'Ang Dandelion ay isang panlabas na serbisyo na maaaring suriin ang iyong nilalaman at magmungkahi ng mga kaugnay na term. %1sI-click dito para sa mga detalye%2s.','This will automatically add new terms from the Dandelion service. Before use, please test carefully using the preview feature.'=>'Awtomatiko nitong idaragdag ang mga bagong term mula sa serbisyo ng Dandelion. Bago gamitin, mangyaring subukan nang maingat gamit ang preview na tampok.','Enable Dandelion'=>'Paganahin ang Dandelion','API Token'=>'API Token','Enter your Dandelion API Key.'=>'Ilagay ang iyong Dandelion API Key.','API Confidence Value'=>'API Confidence Value','Choose a value between 0 and 1. A high value such as 0.8 will provide a few, accurate suggestions. A low value such as 0.2 will produce more suggestions, but they may be less accurate.'=>'Pumili ng halaga sa pagitan ng 0 at 1. Ang mataas na halaga tulad ng 0.8 ay magbibigay ng kaunti, tumpak na mungkahi. Ang mababang halaga tulad ng 0.2 ay magbibigay ng mas maraming mungkahi, ngunit maaaring hindi ito gaanong tumpak.','LSEG / Refinitiv is an external service that can scan your content and suggest relevant terms. %1sClick here for details%2s.'=>'Ang LSEG / Refinitiv ay isang panlabas na serbisyo na maaaring suriin ang iyong nilalaman at magmungkahi ng mga kaugnay na termino. %1sMag-click dito para sa mga detalye%2s.','This will automatically add new terms from the LSEG / Refinitiv service. Before use, please test carefully using the preview feature.'=>'Awtomatikong idaragdag nito ang mga bagong termino mula sa serbisyo ng LSEG / Refinitiv. Bago gamitin, mangyaring subukan nang mabuti gamit ang preview feature.','Enable LSEG / Refinitiv'=>'I-enable ang LSEG / Refinitiv','Enter your LSEG / Refinitiv API Key.'=>'Ilagay ang iyong LSEG / Refinitiv API Key.','Regular Expressions'=>'Regular Expressions','Use Regular Expressions to change how Auto Terms analyzes your posts. This works for terms added when posts are saved or added via the "Schedule" feature.'=>'Gamitin ang Regular Expressions para baguhin kung paano sinusuri ng Auto Terms ang iyong mga post. Ito ay gumagana para sa mga terminong idinadagdag kapag ang mga post ay nai-save o idinadagdag sa pamamagitan ng "Schedule" na tampok.','Regex code'=>'Regex code','Example: <code>/\\b({term})\\b/i</code> will match the whole word while <code>/({term})/i</code> will match at any location even if it\'s part of another word. <code>{term}</code> will be replaced with the term name before the regex action.'=>'Halimbawa: <code>/\\b({term})\\b/i</code> ay tutugma sa buong salita habang ang <code>/({term})/i</code> ay tutugma sa anumang lokasyon kahit na bahagi ito ng ibang salita. Ang <code>{term}</code> ay papalitan ng pangalan ng termino bago ang aksyon ng regex.','Auto Terms successfully copied.'=>'Matagumpay na nakopya ang Auto Terms.','Copy'=>'Kopyahin','Hourly'=>'Bawat Oras','Daily'=>'Araw-araw','Primary Term Name'=>'Pangunahing Pangalan ng Termino','Secondary Term Name'=>'Pangalawang Pangalan ng Termino','Primary Term Taxonomy'=>'Pangunahing Taxonomy ng Termino','Secondary Term Taxonomy'=>'Pangalawang Taxonomy ng Termino','Primary Term Post Count'=>'Bilang ng Post ng Pangunahing Termino','Secondary Term Post Count'=>'Bilang ng Post ng Pangalawang Termino','Add primary term to posts with secondary term'=>'Idagdag ang pangunahing termino sa mga post na may pangalawang termino','Add secondary term to posts with primary term'=>'Idagdag ang pangalawang termino sa mga post na may pangunahing termino','Delete Relationship'=>'Tanggalin ang Relasyon','Taxonomy'=>'Taxonomy','Filter'=>'Salain','Error deleting linked term relationship.'=>'Error sa pagtanggal ng nakalink na relasyon ng termino.','Linked terms deleted successfully.'=>'Matagumpay na natanggal ang mga nakalink na termino.','Linked term deleted successfully.'=>'Matagumpay na natanggal ang nakalink na termino.','%d posts updated successfully.'=>'%d mga post ang matagumpay na na-update.','0 post update.'=>'0 pag-update ng post.','No linked terms found.'=>'Walang mga nakalink na termino na natagpuan.','Number of items per page'=>'Bilang ng mga item bawat pahina','This feature allows you to connect terms. When the primary or secondary term is added to a post, the other term can be added also.'=>'Ang tampok na ito ay nagpapahintulot sa iyo na kumonekta ng mga termino. Kapag ang pangunahing o pangalawang termino ay idinagdag sa isang post, ang ibang termino ay maaari ring idagdag.','Search results for &#8220;%s&#8221;'=>'Mga resulta ng paghahanap para sa &#8220;%s&#8221;','Search Terms'=>'Mga Termino sa Paghahanap','Description here.'=>'Paglalarawan dito.','Start typing to choose existing terms.'=>'Mag-umpisa ng pag-type upang pumili ng mga umiiral na termino.','These terms are linked to the main term. When the primary or secondary term is added to a post, the other term can be added also.'=>'Ang mga terminong ito ay nakalink sa pangunahing termino. Kapag ang pangunahing o pangalawang termino ay idinagdag sa isang post, ang ibang termino ay maaari ring idagdag.','The superscript %1$s indicates the linked term being the primary term, while %2$s is shown when the linked term is the secondary term. You can delete the relationship and re-add it from your preferred term edit screen to make them the primary term.'=>'Ang superscript %1$s ay nagpapahiwatig na ang nakalink na termino ay ang pangunahing termino, habang ang %2$s ay ipinapakita kapag ang nakalink na termino ay ang pangalawang termino. Maaari mong tanggalin ang relasyon at muling idagdag ito mula sa iyong piniling screen ng pag-edit ng termino upang gawin silang pangunahing termino.','Term Synonyms'=>'Mga Kasingkahulugan ng Termino','Type the synonym name (comma-separated) and then click Enter or Return.'=>'I-type ang pangalan ng kasingkahulugan (pinaghiwalay ng kuwit) at pagkatapos ay i-click ang Enter o Return.','If TaxoPress scans your content and finds a synonym, it will act as if it has found the main term.'=>'Kung sinisiyasat ng TaxoPress ang iyong nilalaman at natagpuan ang isang kasingkahulugan, ito ay kikilos na parang natagpuan nito ang pangunahing termino.','This synonym can\'t be added because %1$s is a term on this site.'=>'Ang kasingkahulang ito ay hindi maidaragdag dahil ang %1$s ay isang termino sa site na ito.','These synonyms can\'t be added because %1$s are terms on this site.'=>'Ang mga kasingkahulang ito ay hindi maidaragdag dahil ang %1$s ay mga termino sa site na ito.','This synonym can\'t be added because %1$s is already added to another term.'=>'Ang kasingkahulang ito ay hindi maidaragdag dahil ang %1$s ay naidagdag na sa ibang termino.','These synonyms can\'t be added because %1$s are already added to another term.'=>'Ang mga kasingkahulang ito ay hindi maidaragdag dahil ang %1$s ay naidagdag na sa ibang termino.','%1$s can\'t be added as a tag because %2$s is already used as a synonym.'=>'%1$s ay hindi maidaragdag bilang isang tag dahil ang %2$s ay ginagamit na bilang isang kasingkahulugan.','Request status.'=>'Katayuan ng kahilingan.','Security error. Kindly reload this page and try again'=>'Error sa seguridad. Mangyaring i-reload ang pahinang ito at subukang muli.','Default'=>'Default','Dropdown'=>'Dropdown','Checkbox'=>'Checkbox','Taxonomy Display'=>'Ipakita ang Taxonomy','Enable IBM Watson integration'=>'I-enable ang IBM Watson integration','Show IBM Watson as an AI source for Auto Terms'=>'Ipakita ang IBM Watson bilang isang AI source para sa Auto Terms','Enable Dandelion integration'=>'I-enable ang Dandelion integration','Show Dandelion as an AI source for Auto Terms.'=>'Ipakita ang Dandelion bilang isang AI source para sa Auto Terms.','Enable LSEG/Refinitiv integration'=>'I-enable ang LSEG/Refinitiv integration','Show LSEG/Refinitiv as an AI source for Auto Terms'=>'Ipakita ang LSEG/Refinitiv bilang isang AI source para sa Auto Terms','Term successfully copied with metadata.'=>'Matagumpay na nakopya ang termino kasama ang metadata.','Copy with Metadata'=>'Kopyahin kasama ang Metadata']];